from format_lecon import paras
from antibiotiques_parenteraux import citation, passage

def radioiode(l):
    d=paras('L’iode 131 est capté par le tissu thyroïdien capable d’accumuler l’iode ; son irradiation détruit des follicules. Le choix vise une réduction de fonction ou de volume dans une situation sélectionnée. Le délai d’effet et le risque inflammatoire initial le rendent inadapté comme geste de secours immédiat d’une compression menaçante.',
        'La spécialité suisse documentée est Sodium iodide (I-131) capsule T Curium, autorisation 52728, notice de juillet 2022. Il s’agit d’une capsule radiothérapeutique orale prête à l’emploi. Son activité est mesurée en mégabecquerels ; la dose absorbée au tissu est exprimée en grays. Ces deux grandeurs ne sont pas interchangeables.')
    d+=citation('52728','Comme l’autonomie fonctionnelle de la thyroïde (adénome autonome, autonomies multifocales et disséminées), l’hyperthyroïdie d’origine immunologique (maladie de Basedow) avec et sans goitre et le goitre euthyroïdien.')
    d+=citation('52728',"L'activité à administrer est appréciée par le clinicien. L'effet thérapeutique n'apparaît qu'au bout de plusieurs semaines. L’activité de la capsule doit être déterminée avant utilisation.")
    d+=paras('La notice inclut le goitre euthyroïdien parmi les maladies bénignes traitables. Cela ne signifie pas que tout goitre stable doive recevoir ce traitement. L’activité dépend du diagnostic, du volume, de la fixation et de la clairance. L’équipe de médecine nucléaire utilise son protocole et sa dosimétrie ; aucun nombre issu du traitement d’un cancer n’est transposé au goitre bénin.')
    d+=passage('52728','Contre-indications','Mises en garde et précautions')
    d+=citation('52728',"L'activité à administrer doit être déterminée avec soin, car une exposition accrue aux radiations est possible chez les patients dont la fonction rénale est altérée.")
    d+=citation('52728',"L'utilisation de ce médicament chez l'enfant et l'adolescent doit être décidée à l'issue d'une évaluation soigneuse des besoins cliniques et du rapport bénéfice/risque dans cette population.")
    d+=paras('La grossesse existante, possible ou non exclue contre-indique ce traitement. Une dysphagie ou certaines lésions œsogastriques peuvent aussi contre-indiquer la capsule : la présence d’un symptôme compressif n’autorise pas à faire avaler la capsule de force. L’insuffisance rénale peut augmenter l’irradiation et exige une évaluation spécifique.',
        'Chez l’enfant, la dose efficace par unité d’activité est plus élevée et les indications bénignes sont fortement sélectionnées. Aucun schéma adulte n’est multiplié simplement par le poids. Chez l’adulte comme chez l’enfant, la décision et l’administration relèvent d’un service agréé.')
    d+=citation('52728',"Si l’administration est considérée comme indispensable, l’allaitement maternel doit être interrompu au moins 8 semaines avant l’administration d’iodure ( 131 I) de sodium et ne doit pas être repris (voir rubrique \"Contre-indications\" ).")
    d+=citation('52728','Il convient de conseiller aux femmes traitées par l’iodure de sodium ( 131 l) de ne pas débuter une grossesse dans les 6 à 12 mois suivant l’administration.')
    d+=citation('52728','Après traitement thérapeutique à l’iodure ( 131 I) de sodium, une contraception efficace sera mise en place et maintenue chez l’homme et la femme jusqu’à 6 mois après traitement d’une affection bégnine et jusqu’à 12 mois après traitement d’un cancer thyroïdien.')
    d+=paras('Les restrictions d’allaitement concernent cette administration thérapeutique et doivent être anticipées avec la patiente. La notice comporte aussi des exigences de contraception et des délais avant conception, différents selon le contexte. Le service explique et formalise l’ensemble des consignes de radioprotection et de projet parental ; un résumé de prévention alimentaire ne les remplace pas.',
        'Avant traitement, signaler les médicaments et les expositions iodées qui modifient la fixation. Les arrêts ou reprises d’antithyroïdiens, hormones ou autres traitements se font sur instruction de l’équipe, sans arrêt improvisé par le patient. La préparation et les interactions doivent être contrôlées dans la notice complète.',
        'Surveiller une aggravation transitoire d’hyperthyroïdie, une inflammation thyroïdienne ou une gêne respiratoire. Une sténose trachéale préexistante demande une vigilance particulière. Une hypothyroïdie ultérieure est possible et nécessite un suivi biologique durable. Une réaction d’hypersensibilité pendant l’administration impose son interruption et un traitement approprié.')
    return l.subwindow('radioiode','Iode131 thérapeutique : indication et sécurité suisses',d,(51,48))
